using Fgs.Foundation.Paging;
namespace Fgs.Asset.Infrastructure.AssetAttributeOptions;
internal static class FgsAssetAttributeOptionSql { public const string Table = "asset.\"FgsAssetAttributeOption\""; public const string SelectDetailColumns = "\"Id\", \"AssetAttributeId\", \"OptionCode\", \"OptionName\", \"DisplayOrder\", \"IsActive\""; public const string SelectSummaryColumns = SelectDetailColumns; public const string SelectLookupColumns = "\"Id\", \"OptionCode\", \"OptionName\""; private static readonly HashSet<string> AllowedSortColumns = new(StringComparer.OrdinalIgnoreCase) { "Id", "AssetAttributeId", "OptionCode", "OptionName", "DisplayOrder", "IsActive" }; public static string ResolveOrderBy(string? sortBy, SortDirection direction) { var dir = direction == SortDirection.Desc ? "DESC" : "ASC"; if (string.IsNullOrWhiteSpace(sortBy) || !AllowedSortColumns.Contains(sortBy)) return $"ORDER BY \"DisplayOrder\" {dir}"; return $"ORDER BY \"{AllowedSortColumns.First(c => c.Equals(sortBy, StringComparison.OrdinalIgnoreCase))}\" {dir}"; } }
